// static
bool StructTraits<::psst::mojom::SettingCardDataItem::DataView, ::psst::mojom::SettingCardDataItemPtr>::Read(
    ::psst::mojom::SettingCardDataItem::DataView input,
    ::psst::mojom::SettingCardDataItemPtr* output) {
  bool success = true;
  ::psst::mojom::SettingCardDataItemPtr result(::psst::mojom::SettingCardDataItem::New());
  
      if (success && !input.ReadDescription(&result->description))
        success = false;
      if (success && !input.ReadUid(&result->uid))
        success = false;
  *output = std::move(result);
  return success;
}


// static
