void PsstConsentFactoryAsyncWaiter::CreatePsstConsentHandler(
    ::mojo::PendingReceiver<PsstConsentHelper> psst_consent_helper, ::mojo::PendingRemote<PsstConsentDialog> psst_consent_dialog, SettingCardDataPtr* out_current_site_data) {
  base::RunLoop loop;
  proxy_->CreatePsstConsentHandler(
      std::move(psst_consent_helper),
      std::move(psst_consent_dialog),
      base::BindOnce(
          [](base::RunLoop* loop,
             SettingCardDataPtr* out_current_site_data
,
             SettingCardDataPtr current_site_data) {*out_current_site_data = std::move(current_site_data);
            loop->Quit();
          },
          &loop,
          out_current_site_data));
  loop.Run();
}

